-- Generated from data/national-parks-156.csv by pnpm import:places.
-- Run after migrations as a database administrator. No personal data.
-- Rerunning updates matching IDs; it never deletes other places.
begin;

on conflict (id) do update set
  name = excluded.name,
  location = excluded.location,
  province = excluded.province,
  region = excluded.region,
  description = excluded.description,
  type = excluded.type,
  is_national_park = excluded.is_national_park,
  latitude = excluded.latitude,
  longitude = excluded.longitude,
  altitude = excluded.altitude,
  distance = excluded.distance,
  image_path = excluded.image_path,
  image_author = excluded.image_author,
  image_license = excluded.image_license,
  image_license_url = excluded.image_license_url,
  image_source_url = excluded.image_source_url;

commit;
