  (E'national-park-0ce84171534e', E'อุทยานแห่งชาติกุยบุรี', E'อำเภอกุยบรี', E'ประจวบคีรีขันธ์', E'west', E'ป่าต้นน้ำที่เป็นแหล่งรวมสัตว์ป่าสำคัญของภาคตะวันตก ทั้งช้างป่า วัวแดง กระทิง เสือโคร่ง เสือดาว และพบสัตว์ป่าสงวนหลายชนิด', E'mountain', true, 12.0518, 99.6238, null, null, E'national-park-0ce84171534e.webp', E'KOSIN SUKHUM', E'CC BY-SA 4.0', E'https://creativecommons.org/licenses/by-sa/4.0', E'https://commons.wikimedia.org/wiki/File:Kui_Buri_National_Park_(Prachuap_Khiri_Khan_Province,_Thailand.jpg'),
