  (E'national-park-bdc598cc563b', E'อุทยานแห่งชาติเขาลำปี-หาดท้ายเหมือง', E'อำเภอท้ายเหมือง', E'พังงา', E'south', E'ผสมผสานเทือกเขาป่าดงดิบและหาดทรายขาวริมทะเลอันดามัน มียอดเขาขนิมสูง 622 เมตร ด้านตะวันออกติดป่าชายเลน พบสัตว์ป่าและสัตว์ทะเลหลากชนิด', E'island', true, 8.4393, 98.2361, E'622 m', E'0.65 กม.', E'national-park-bdc598cc563b.webp', E'Rueangrit srisuk', E'CC BY-SA 3.0', E'https://creativecommons.org/licenses/by-sa/3.0', E'https://commons.wikimedia.org/wiki/File:Rueangrit_001u1.jpg'),
  (E'national-park-e304412d7eae', E'อุทยานแห่งชาติเขาหลวง', E'อำเภอลานสกา', E'นครศรีธรรมราช', E'south', E'เทือกเขาสลับซับซ้อนที่มียอดเขาหลวงสูงสุดในภาคใต้ราว 1,835 เมตร เป็นต้นน้ำหลายสาย ป่าดิบชื้นและป่าดิบเขาที่มีพืชสัตว์หายาก พร้อมเส้นทางเดินวงรอบ', E'mountain', true, 8.3688, 99.7354, E'1835 m', E'3.7 กม.', E'national-park-e304412d7eae.webp', E'Adirach Toumlamoon', E'CC BY-SA 4.0', E'https://creativecommons.org/licenses/by-sa/4.0', E'https://commons.wikimedia.org/wiki/File:Phromlok_Waterfall_1.jpg'),
  (E'national-park-b2388b40b2b3', E'อุทยานแห่งชาติเขาหลัก-ลำรู่', E'อำเภอตะกั่วป่า', E'พังงา', E'south', E'เทือกเขาป่าดงดิบสลับซับซ้อน เป็นต้นกำเนิดแม่น้ำพังงาและแม่น้ำตะกั่วป่า มีเส้นทางศึกษาธรรมชาติสู่น้ำตกโตนช่องฟ้า ทางเดินค่อนข้างชัน ต้องมีเจ้าหน้าที่นำทาง', E'island', true, 8.6267, 98.2392, E'1077 m', null, null, null, null, null, null),
  (E'national-park-9c3c290e9660', E'อุทยานแห่งชาติตะรุเตา', E'อำเภอละงู', E'สตูล', E'south', E'อุทยานกลางทะเลอันดามันที่มีเกาะน้อยใหญ่ถึง 51 เกาะ ป่าอุดมสมบูรณ์เป็นถิ่นสัตว์ป่า และแนวปะการังหลากสีสันที่เลื่องชื่อไปทั่วโลก', E'island', true, 6.8606, 99.7222, E'708 m', E'0.3 กม.', E'national-park-9c3c290e9660.webp', E'Vyacheslav Argenberg', E'CC BY 4.0', E'https://creativecommons.org/licenses/by/4.0', E'https://commons.wikimedia.org/wiki/File:Koh_Tarutao,_Thailand,_Rocky_beach.jpg'),
  (E'national-park-79fe3059f0eb', E'อุทยานแห่งชาติทะเลบัน', E'อำเภอควนโดน', E'สตูล', E'south', E'ระบบนิเวศหลากหลายทั้งผืนป่า ภูเขา ถ้ำ และน้ำตก จุดเด่นคือบึงน้ำจืดทะเลบันกลางหุบเขา ซึ่งเชื่อว่าเกิดจากพื้นดินยุบตัว มีน้ำจากผนังเขาไหลหล่อเลี้ยง', E'mountain', true, 6.709, 100.1691, E'756 m', null, E'national-park-79fe3059f0eb.webp', E'KOSIN SUKHUM', E'CC BY-SA 4.0', E'https://creativecommons.org/licenses/by-sa/4.0', E'https://commons.wikimedia.org/wiki/File:Thale_Ban_National_Park_Satun_Thailand.jpg'),
  (E'national-park-9c05ec5d8c89', E'อุทยานแห่งชาติธารโบกขรณี', E'อำเภออ่าวลึก', E'กระบี่', E'south', E'แหล่งธรรมชาติที่มีน้ำตก ธารน้ำไหลผ่านโขดหิน และป่าเขาเขียวขจี ตั้งแต่ป่าดิบชื้นถึงภูเขาหินปูน มีเส้นทางเดินป่า ปีนเขา และดูนก', E'waterfall', true, 8.3887, 98.7346, null, E'0.3 กม.', E'national-park-9c05ec5d8c89.webp', E'Vyacheslav Argenberg', E'CC BY 4.0', E'https://creativecommons.org/licenses/by/4.0', E'https://commons.wikimedia.org/wiki/File:Streams,_rivers_and_mangrove_forests_of_Than_Bok_Khorani,_Thailand.jpg'),
  (E'national-park-8ad3c4bde9d2', E'อุทยานแห่งชาติน้ำตกโยง', E'อำเภอทุ่งสง', E'นครศรีธรรมราช', E'south', E'ผืนป่าเทือกเขาหลวงในนครศรีธรรมราช ที่มีน้ำตกโยงเป็นชื่อประจำอุทยาน เป็นอุทยานแห่งชาติลำดับที่ 64 ของประเทศไทย', E'waterfall', true, 8.1722, 99.7417, E'1235 m', null, E'national-park-8ad3c4bde9d2.webp', E'Pakon2709', E'CC BY-SA 4.0', E'https://creativecommons.org/licenses/by-sa/4.0', E'https://commons.wikimedia.org/wiki/File:%E0%B8%99%E0%B9%89%E0%B8%B3%E0%B8%95%E0%B8%81%E0%B9%82%E0%B8%A2%E0%B8%87_5.jpg'),
  (E'national-park-36cb32f048e9', E'อุทยานแห่งชาติน้ำตกสี่ขีด', E'อำเภอสิชล', E'นครศรีธรรมราช', E'south', E'พื้นที่ธรรมชาติสวยงามที่มีน้ำตก เกาะแก่ง แอ่งน้ำ และโขดหิน พร้อมพันธุ์ไม้หลากหลาย เป็นป่าต้นน้ำที่ชุมชนใช้ประโยชน์ทางเกษตรกรรม', E'waterfall', true, 9.0146, 99.7712, E'1303 m', null, E'national-park-36cb32f048e9.webp', E'Chaiyathat', E'CC BY-SA 4.0', E'https://creativecommons.org/licenses/by-sa/4.0', E'https://commons.wikimedia.org/wiki/File:Namtok_Si_Khit_National_Park_(3)A.jpg'),
  (E'national-park-a5d31ebbcc32', E'อุทยานแห่งชาติศรีพังงา', E'อำเภอคุระบุรี', E'พังงา', E'south', E'ป่าดิบชื้นสมบูรณ์บนเทือกเขานมสาว มีไม้ยาง ตะเคียนทอง ปาล์ม และกล้วยไม้อย่างรองเท้านารี เป็นถิ่นสัตว์ป่า เช่น สมเสร็จ เลียงผา วัวแดง และนกเงือก', E'waterfall', true, 8.9983, 98.4579, null, E'2 กม.', E'national-park-a5d31ebbcc32.webp', E'Setaphong Tantanawat', E'CC BY-SA 4.0', E'https://creativecommons.org/licenses/by-sa/4.0', E'https://commons.wikimedia.org/wiki/File:%E0%B8%99%E0%B9%89%E0%B8%B3%E0%B8%95%E0%B8%81%E0%B8%95%E0%B8%B3%E0%B8%AB%E0%B8%99%E0%B8%B1%E0%B8%87.jpg'),
  (E'national-park-f8a64c10e0fd', E'อุทยานแห่งชาติสิรินาถ', E'อำเภอถลาง', E'ภูเก็ต', E'south', E'หาดทรายเงียบสงบร่มรื่นด้วยทิวสนและพรรณไม้ป่าชายหาด ยาวต่อเนื่อง 13 กิโลเมตร และมีเส้นทางศึกษาธรรมชาติป่าชายเลนให้เที่ยวชม', E'island', true, 8.0956, 98.3003, null, E'0.6 กม.', E'national-park-f8a64c10e0fd.webp', E'Andy Mitchell from Glasgow, UK', E'CC BY-SA 2.0', E'https://creativecommons.org/licenses/by-sa/2.0', E'https://commons.wikimedia.org/wiki/File:Nai_Yang_Beach,_Phuket_(4448621322).jpg'),
  (E'national-park-c3240be3a269', E'อุทยานแห่งชาติหมู่เกาะเภตรา', E'อำเภอละงู', E'สตูล', E'south', E'หมู่เกาะราว 22 เกาะในทะเลสตูล ที่มีหน้าผา หาดทราย และจุด ''เขตข้ามกาลเวลา'' ซึ่งหินทรายยุคแคมเบรียนมาสัมผัสกับหินปูนยุคออร์โดวิเชียน', E'island', true, 6.8354, 99.755, null, null, E'national-park-c3240be3a269.webp', E'Lerdsuwa', E'CC BY-SA 3.0', E'https://creativecommons.org/licenses/by-sa/3.0/', E'https://commons.wikimedia.org/wiki/File:KoPetraFromLaoLiang.jpg'),
  (E'national-park-c862b3d054af', E'อุทยานแห่งชาติหมู่เกาะลันตา', E'อำเภอลันตา', E'กระบี่', E'south', E'หมู่เกาะริมทะเลอันดามันที่มีหาดทรายขาวละเอียด น้ำทะเลใส และแนวปะการังหลากสี เหมาะกับดำน้ำและพายคายัค อีกทั้งมีวิถีชีวิตชาวเลที่น่าสนใจ', E'island', true, 7.4705, 99.0978, E'488 m', null, E'national-park-c862b3d054af.webp', E'Neitram', E'CC BY-SA 3.0', E'https://creativecommons.org/licenses/by-sa/3.0/', E'https://commons.wikimedia.org/wiki/File:Thailand_koh_lanta_beach.jpg'),
  (E'national-park-083f49a9cc1e', E'อุทยานแห่งชาติหมู่เกาะสิมิลัน', E'อำเภอท้ายเหมือง', E'พังงา', E'south', E'หมู่เกาะ 9 เกาะกลางทะเลอันดามัน ขึ้นชื่อเรื่องความสมบูรณ์ทั้งบนบกและใต้น้ำ ดำน้ำตื้นและน้ำลึกชมปะการังหลากสี ปลาการ์ตูน และกระเบนราหู', E'island', true, 8.5716, 98.2297, E'244 m', null, E'national-park-083f49a9cc1e.webp', E'Varakorn Kuldilok', E'CC BY-SA 3.0', E'https://creativecommons.org/licenses/by-sa/3.0', E'https://commons.wikimedia.org/wiki/File:%E0%B8%97%E0%B8%B4%E0%B8%A7%E0%B8%97%E0%B8%B1%E0%B8%A8%E0%B8%99%E0%B9%8C%E0%B8%88%E0%B8%B2%E0%B8%81%E0%B8%AA%E0%B8%B4%E0%B8%A1%E0%B8%B4%E0%B8%A5%E0%B8%B1%E0%B8%99_%E0%B9%80%E0%B8%81%E0%B8%B2%E0%B8%B08.jpg'),
  (E'national-park-fd2b0a6c4208', E'อุทยานแห่งชาติหมู่เกาะสุรินทร์', E'อำเภอคุระบุรี', E'พังงา', E'south', E'อุทยานทางทะเลที่สวยงามและอุดมสมบูรณ์ ด้วยน้ำใสและปะการังน้ำตื้นกว้างใหญ่ และเป็นถิ่นอาศัยของชาวมอแกนที่ยังรักษาวัฒนธรรมและการทำเรือไม้ดั้งเดิม', E'island', true, 9.2263, 98.3745, null, null, E'national-park-fd2b0a6c4208.webp', E'The Cosmonaut', E'CC BY-SA 2.5 ca', E'https://creativecommons.org/licenses/by-sa/2.5/ca/deed.en', E'https://commons.wikimedia.org/wiki/File:Moken_Village1.jpg'),
  (E'national-park-e5164df5b636', E'อุทยานแห่งชาติหาดขนอม-หมู่เกาะทะเลใต้', E'อำเภอขนอม', E'นครศรีธรรมราช', E'south', E'หาดทรายยื่นยาวคู่ทิวสนและเกาะมัตโกง เกาะมัตสุ่ม ที่ดำน้ำชมปะการังได้ จุดเด่นคือโลมาสีชมพูที่พบได้ง่ายที่หาดขนอม และเกาะนุ้ยนอกอันเป็นตำนานหลวงปู่ทวด', E'island', true, 8.4052, 98.5081, E'814 m', null, E'national-park-e5164df5b636.webp', E'Ahoerstemeier', E'CC BY-SA 3.0', E'https://creativecommons.org/licenses/by-sa/3.0/', E'https://commons.wikimedia.org/wiki/File:Khanom_Beach.jpg'),
  (E'national-park-7e93a552a638', E'อุทยานแห่งชาติหาดเจ้าไหม', E'อำเภอสิเกา', E'ตรัง', E'south', E'อุทยานทางทะเลของตรังที่มีชายหาดต่อเนื่องราว 20 กิโลเมตร ถ้ำเจ้าไหม และเกาะน้อยใหญ่ 7 เกาะ รวมถึงศูนย์ศึกษาธรรมชาติที่วิจัยหญ้าทะเล', E'island', true, 9.1081, 99.9025, null, null, E'national-park-7e93a552a638.webp', E'Khunkay', E'CC BY-SA 3.0', E'https://creativecommons.org/licenses/by-sa/3.0', E'https://commons.wikimedia.org/wiki/File:Koh_Ngai_07.jpg'),
  (E'place-phi-phi', E'อุทยานแห่งชาติหาดนพรัตน์ธารา-หมู่เกาะพีพี', E'อำเภอเมือง', E'กระบี่', E'south', E'เขาหินปูน ป่าชายเลน หาดทรายขาว และปะการังในทะเลกระบี่ มีหมู่เกาะพีพีที่โด่งดัง ทั้งอ่าวมาหยาและถ้ำไวกิ้งที่มีภาพวาดโบราณและรังนกนางแอ่น', E'island', true, 7.4128, 99.345, null, null, E'place-phi-phi.webp', E'Puripant', E'CC BY-SA 4.0', E'https://creativecommons.org/licenses/by-sa/4.0', E'https://commons.wikimedia.org/wiki/File:From_a_Beach_in_Phi_Phi_Don.jpg'),
  (E'national-park-67a08fa60c6a', E'อุทยานแห่งชาติอ่าวพังงา', E'อำเภอเมือง', E'พังงา', E'south', E'อุทยานชายฝั่งทะเลที่พื้นที่ส่วนใหญ่เป็นทะเลและเกาะ มีเขาหินปูนรูปร่างงดงามหลากหลาย ป่าชายเลนสมบูรณ์ และเป็นแหล่งขยายพันธุ์สัตว์น้ำ', E'island', true, 8.0472, 98.7991, null, null, E'national-park-67a08fa60c6a.webp', E'Diego Delso', E'CC BY-SA 3.0', E'https://creativecommons.org/licenses/by-sa/3.0', E'https://commons.wikimedia.org/wiki/File:Isla_Tapu,_Phuket,_Tailandia,_2013-08-20,_DD_36.JPG'),
  (E'national-park-9766621066a9', E'อุทยานแห่งชาติเขาน้ำค้าง', E'อำเภอนาทวี', E'สงขลา', E'south', E'ยอดเขาสูงให้ชมทิวทัศน์ชายแดนฝั่งมาเลเซีย อากาศหนาวเย็นตลอดปี ชื่อเขาน้ำค้างมาจากน้ำค้างที่จับเป็นเกล็ดบนยอดหญ้า', E'mountain', true, 6.5992, 100.5877, E'648 m', E'4 กม.', E'national-park-9766621066a9.webp', E'Earng.oi', E'CC BY-SA 4.0', E'https://creativecommons.org/licenses/by-sa/4.0', E'https://commons.wikimedia.org/wiki/File:Khao_Nam_Khang_National_Park_in_Songkhla,_Thailand.jpg'),
