  (E'national-park-84631c3a24df', E'อุทยานแห่งชาติน้ำตกพาเจริญ', E'อำเภอพบพระ', E'ตาก', E'west', E'น้ำตกหินปูนที่ไหลลดหลั่นถึง 97 ชั้นและมีน้ำตลอดปี พร้อมทุ่งดอกกระเจียวสีส้มช่วงกรกฎาคม-ตุลาคม บ่อน้ำร้อนธรรมชาติ จุดชมทะเลหมอกริมแม่น้ำเมย และน้ำตกป่าหวาย', E'waterfall', true, 16.5022, 98.7525, E'1765 m', null, E'national-park-84631c3a24df.webp', E'Somphongph', E'CC BY-SA 4.0', E'https://creativecommons.org/licenses/by-sa/4.0', E'https://commons.wikimedia.org/wiki/File:%E0%B8%AD%E0%B8%B8%E0%B8%97%E0%B8%A2%E0%B8%B2%E0%B8%99%E0%B9%81%E0%B8%AB%E0%B9%88%E0%B8%87%E0%B8%8A%E0%B8%B2%E0%B8%95%E0%B8%B4%E0%B8%99%E0%B9%89%E0%B8%B3%E0%B8%95%E0%B8%81%E0%B8%9E%E0%B8%B2%E0%B9%80%E0%B8%88%E0%B8%A3%E0%B8%B4%E0%B8%8D.jpg'),
