  (E'national-park-7d6c8e5c33c6', E'อุทยานแห่งชาติผาแดง', E'อำเภอเชียงดาว', E'เชียงใหม่', E'north', E'ป่าต้นน้ำของแม่น้ำปิงและแม่แตงบนเทือกเขาสลับซับซ้อน มีน้ำตกศรีสังวาลย์ น้ำตกปางตอง ถ้ำ บ่อน้ำร้อนโป่งอาง จุดชมวิวดอยผาแดง และหลักฐานทางประวัติศาสตร์', E'mountain', true, 19.6287, 98.9562, E'1794 m', null, null, null, null, null, null),
  (E'national-park-7ed1eca95fd9', E'อุทยานแห่งชาติแม่ตะไคร้', E'อำเภอดอยสะเก็ด', E'เชียงใหม่', E'north', E'ป่าต้นน้ำหลายประเภทที่มีอ่างเก็บน้ำแม่ตะไคร้และเส้นทางเดินป่า น้ำตกตาดเหมย จุดชมวิวเมืองเชียงใหม่และดอยสุเทพ และดอยลังกาสูง 2,030 เมตรที่มีกุหลาบพันปี', E'mountain', true, 18.9664, 99.2419, null, null, null, null, null, null, null),
